'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { ArrowRight, ChevronLeft, X } from 'lucide-react';
import { StylePreference } from '@/lib/types/user-profile-types';
import useEmblaCarousel from 'embla-carousel-react';
import fashionStylesData from '@/lib/data/fashion-styles.json';

interface OnboardingStyleProps {
  onNext: (styles: StylePreference[]) => void;
  onBack: () => void;
}

// Import fashion styles from single source of truth
const styleOptions = fashionStylesData as StylePreference[];

export function OnboardingStyle({ onNext, onBack }: OnboardingStyleProps) {
  const [selectedStyles, setSelectedStyles] = useState<StylePreference[]>([]);
  const [failedImages, setFailedImages] = useState<Set<string>>(new Set());

  const [emblaRef] = useEmblaCarousel({
    align: 'start',
    containScroll: false,
    dragFree: true,
  });

  const handleImageError = (styleId: string) => {
    setFailedImages((prev) => new Set(prev).add(styleId));
  };

  const toggleStyle = (style: StylePreference) => {
    setSelectedStyles((prev) => {
      const isSelected = prev.some((s) => s.id === style.id);
      if (isSelected) {
        return prev.filter((s) => s.id !== style.id);
      } else {
        return [...prev, style];
      }
    });
  };

  const removeStyle = (styleId: string) => {
    setSelectedStyles((prev) => prev.filter((s) => s.id !== styleId));
  };

  const handleNext = () => {
    if (selectedStyles.length > 0) {
      onNext(selectedStyles);
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-[var(--onboarding-bg)]">
      {/* Back Button */}
      <div className="p-4">
        <Button
          variant="ghost"
          onClick={onBack}
          className="text-gray-600 hover:text-gray-900"
        >
          <ChevronLeft className="w-5 h-5" />
        </Button>
      </div>

      {/* Content */}
      <div className="flex-1 flex flex-col p-6">
        <div className="max-w-4xl w-full mx-auto space-y-6">
          {/* Heading - Left Aligned */}
          <div className="text-left space-y-1">
            <h1 className="text-3xl font-bold text-[var(--onboarding-primary)]">
              What&apos;s your style?
            </h1>
            <p className="text-base text-gray-900">
              Choose style that sparks you
            </p>
          </div>

          {/* Selected Styles Thumbnails - Below Header, Left Aligned */}
          {selectedStyles.length > 0 && (
            <div className="flex gap-3 overflow-x-auto pb-2 hide-scrollbar">
              {selectedStyles.map((style) => (
                <div
                  key={style.id}
                  className="relative flex-shrink-0 w-[60px] h-[80px] rounded-lg overflow-hidden border-2 border-[var(--onboarding-card-border-selected)] selection-thumbnail-enter"
                >
                  <img
                    src={style.imageUrl || '/images/styles/Group 40.png'}
                    alt={`${style.name} style`}
                    className="absolute inset-0 w-full h-[120%] object-cover object-top"
                  />
                  <button
                    onClick={() => removeStyle(style.id)}
                    className="absolute top-1 right-1 w-5 h-5 bg-[var(--onboarding-primary)] rounded-full flex items-center justify-center shadow-sm hover:bg-[var(--onboarding-primary-hover)] transition-colors"
                  >
                    <X className="w-3 h-3 text-white" />
                  </button>
                </div>
              ))}
            </div>
          )}

          {/* Carousel */}
          <div className="overflow-hidden -mx-6" ref={emblaRef}>
            <div className="flex gap-4 px-6"
              style={{ scrollSnapType: 'x mandatory' }}
            >
              {styleOptions.map((style) => {
                const isSelected = selectedStyles.some((s) => s.id === style.id);
                return (
                  <div
                    key={style.id}
                    className="flex-[0_0_160px] min-w-0"
                    style={{ scrollSnapAlign: 'start' }}
                  >
                    <button
                      onClick={() => toggleStyle(style)}
                      className={`
                        w-full rounded-2xl overflow-hidden
                        bg-white shadow-sm selection-carousel-card carousel-card-border
                        border-2 ${isSelected ? 'border-[var(--onboarding-card-border-selected)] carousel-card-selected' : 'border-[var(--onboarding-card-border)]'}
                      `}
                    >
                      {/* Style Image - Cropped to hide baked-in text at bottom */}
                      <div className="w-full aspect-[3/4] overflow-hidden rounded-t-2xl relative">
                        {style.imageUrl && !failedImages.has(style.id) ? (
                          <img
                            src={style.imageUrl}
                            alt={`${style.name} style`}
                            loading="lazy"
                            onError={() => handleImageError(style.id)}
                            className="absolute inset-0 w-full h-[120%] object-cover object-top"
                          />
                        ) : (
                          <div className="absolute inset-0 bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">
                            <span className="text-4xl">👗</span>
                          </div>
                        )}
                      </div>

                      {/* Card Content - Inside white card, centered, fixed height */}
                      <div className="p-3 h-[72px] flex flex-col justify-start">
                        {/* Style Title - Black Text: "Name · Description", centered */}
                        <h3 className="text-sm font-bold text-gray-900 text-center">
                          {style.name} · {style.description}
                        </h3>

                        {/* Card Description - Gray Text, centered */}
                        {style.cardDescription && (
                          <p className="mt-2 text-xs text-gray-500 text-center line-clamp-2">
                            {style.cardDescription}
                          </p>
                        )}
                      </div>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Scroll Position Indicators */}
          {scrollSnaps.length > 1 && (
            <CarouselDots
              selectedIndex={selectedIndex}
              scrollSnaps={scrollSnaps}
              onDotClick={scrollTo}
            />
          )}

          {/* Next Button - Circular Red, Bottom Center */}
          <div className="flex justify-center pt-6">
            <Button
              onClick={handleNext}
              disabled={selectedStyles.length === 0}
              className="w-14 h-14 rounded-full bg-[var(--onboarding-primary)] hover:bg-[var(--onboarding-primary-hover)] text-white disabled:bg-gray-300 disabled:cursor-not-allowed"
            >
              <ArrowRight className="w-6 h-6" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

